            border-radius: 4px;
        }

        /* --- Filters & Summary Section --- */
        #filters {
            display: flex;
            gap: 20px;
            margin-bottom: 30px;
            padding: 15px;
            background-color: #eaf7ff;
            border-radius: 6px;
            flex-wrap: wrap;
        }

        #filters .form-group {
            margin: 0;
        }

        .filter-group label {
            min-width: auto; /* Allow date inputs to flow naturally */
            display: inline-block;
