<body>

<div class="container">
    <h1>💰 Personal Expense Tracker</h1>

    <!-- Entry Form -->
    <section id="entry-form">
        <h2>Add New Expense</h2>
        <div class="form-group">
            <label for="amount">Amount ($):</label>
            <input type="number" id="amount" placeholder="e.g., 15.50" min="0.01" step="0.01" required>
        </div>

        <div class="form-group">
            <label for="category">Category:</label>
            <select id="category" required>
                <!-- Options filled by JS -->
            </select>
        </div>

        <div class="form-group">
             <label for="date">Date:</label>
            <input type="date" id="date" required>
        </div>

        <div class="form-group">
            <label for="note">Note (Optional):</label>
            <input type="text" id="note" placeholder="Coffee, rent payment, etc.">
        </div>

        <button id="add-expense">Add Expense</button>
        <div id="form-error"></div>
    </section>

    <!-- Filters -->
    <section id="filters">
        <div class="filter-group form-group" style="flex: 1;">
            <label for="filter-category">Category:</label>
            <select id="filter-category">
                <option value="all">All Categories</option>
                <!-- Options filled by JS -->
            </select>
        </div>

        <div class="filter-group form-group" style="flex: 1;">
            <label for="filter-from">From Date:</label>
            <input type="date" id="filter-from" style="width: 100%;">
        </div>

        <div class="filter-group form-group" style="flex: 1;">
            <label for="filter-to">To Date:</label>
            <input type="date" id="filter-to" style="width: 100%;">
        </div>
    </section>

    <!-- Summary Area -->
    <div id="summary-area">
        <div>Visible Totals By Category:</div>
        <div id="category-summaries">
            <!-- Cat totals go here -->
        </div>
        <div>Total Spent: <span id="total">$0.00</span></div>
    </div>

    <!-- Expense List -->
    <h2>Expense History</h2>
    <ul id="expense-list">
        <!-- Expenses will be rendered here -->
    </ul>

</div>

<script>
    document.addEventListener('DOMContentLoaded', () => {
        const expenseListEl = document.getElementById('expense-list');
        const formErrorEl = document.getElementById('form-error');
        const amountInput = document.getElementById('amount');
        const categorySelect = document.getElementById('category');
        const dateInput = document.getElementById('date');
        const noteInput = document.getElementById('note');
        const addButton = document.getElementById('add-expense');

        // Filter controls
        const filterCategoryEl = document.getElementById('filter-category');
        const filterFromEl = document.getElementById('filter-from');
        const filterToEl = document.getElementById('filter-to');

        // Summary controls
        const totalDisplayEl = document.getElementById('total');
        const categorySummariesEl = document.getElementById('category-summaries');


        let expenses = loadExpenses();
        const CATEGORIES = ['groceries', 'transport', 'bills', 'fun'];
        const STORAGE_KEY = 'expenseTrackerData';

        // --- Data Persistence and Initialization ---

        /** Loads expenses from localStorage, ensuring it's an array. */
        function loadExpenses() {
            try {
                const storedData = localStorage.getItem(STORAGE_KEY);
                return storedData ? JSON.parse(storedData) : [];
            } catch (e) {
                console.error("Could not load expenses from local storage", e);
                return [];
            }
        }

        /** Saves the current expenses array to localStorage. */
        function saveExpenses() {
            localStorage.setItem(STORAGE_KEY, JSON.stringify(expenses));
        }

        // --- UI Population (Selects) ---

        /** Populates category and filter selects with options. */
        function populateControls() {
            let optionsHtml = '';
            CATEGORIES.forEach(cat => {
                // 1. Main Form Select
                optionsHtml += `<option value="${cat}">${cat.charAt(0).toUpperCase() + cat.slice(1)}</option>`;

                // 2. Filter Select
                const filterOption = document.createElement('option');
                filterOption.value = cat;
                filterOption.textContent = cat.charAt(0).toUpperCase() + cat.slice(1);
                filterCategoryEl.appendChild(filterOption);
            });

            // Set initial date to today for convenience (optional UX improvement)
            const today = new Date().toISOString().split('T')[0];
            dateInput.setAttribute('min', today); 
        }

        // --- Validation and Submission ---

        /** Handles the addition of a new expense record. */
        function addExpense(e) {
            e.preventDefault();

            const amount = parseFloat(amountInput.value);
            const category = categorySelect.value;
            const date = dateInput.value;
            const note = noteInput.value.trim();

            // 1. Validation checks
            if (isNaN(amount) || amount <= 0) {
                displayError("Please enter a valid positive amount.");
                return;
            }
            if (!date) {
                displayError("Date is required for the expense.");
                return;
            }

            // Clear previous errors
            formErrorEl.innerHTML = '';

            // 2. Create new expense object
            const newExpense = {
                id: Date.now(), // Simple unique ID
                amount: amount,
                category: category,
                date: date,
                note: note || null,
                timestamp: Date.now() // For sorting
            };

            // 3. Update state and UI
            expenses.unshift(newExpense); // Add to the beginning (newest)
            saveExpenses();

            // Reset form inputs for clean UX
            amountInput.value = '';
            noteInput.value = '';
            displayError(''); // Clear any potential lingering error messages

            // Re-render everything based on current filters
            render();
        }

        /** Displays a user-friendly error message. */
        function displayError(message) {
            formErrorEl.textContent = message;
        }


        // --- Rendering and Calculations ---

        /** Filters the full expenses list based on filter inputs. */
        function getVisibleExpenses() {
            const selectedCategory = filterCategoryEl.value;
            const fromDate = filterFromEl.value;
            const toDate = filterToEl.value;

            return expenses.filter(expense => {
                // Category filter check
                if (selectedCategory !== 'all' && expense.category !== selectedCategory) {
                    return false;
                }

                // Date range check
                const expenseDate = expense.date;
                if (fromDate && expenseDate < fromDate) {
                    return false;
                }
                if (toDate && expenseDate > toDate) {
                    return false;
                }
                return true;
            });
        }

        /** Renders the filtered list and recalculates summaries. */
        function render() {
            const visibleExpenses = getVisibleExpenses();

            // Sort by date (newest first is easiest, but let's sort numerically based on stored timestamps just in case)
             visibleExpenses.sort((a, b) => b.timestamp - a.timestamp);


            expenseListEl.innerHTML = ''; // Clear list

            let totalSpent = 0;
            const categoryTotalsMap = new Map();

            // Step 1: Build List and Calculate Totals
            visibleExpenses.forEach(expense => {
                totalSpent += expense.amount;

                // Update Category Summary Map
                if (!categoryTotalsMap.has(expense.category)) {
                    categoryTotalsMap.set(expense.category, 0);
                }
                categoryTotalsMap.set(expense.category, categoryTotalsMap.get(expense.category) + expense.amount);

                // Create list item HTML structure
                const li = document.createElement('li');
                li.className = 'expense';
                li.dataset.id = expense.id; // Store ID for easy deletion
                li.innerHTML = `
                    <div class="exp-info">
                        <div class="exp-details">
                            <strong>${expense.note || 'No note'}</strong> 
                            <span>Category: ${expense.category.replace('-', ' ')}</span>
                            <span>Date: ${expense.date}</span>
                        </div>
                    </div>
                    <span class="expense-amount">$${expense.amount.toFixed(2)}</span>
                    <div class="expense-date">${expense.date}</div>
                    <button class="exp-del" data-id="${expense.id}">Delete</button>
                `;
                expenseListEl.appendChild(li);
            });

            // Step 2: Update Summary Display (Total)
            totalDisplayEl.textContent = `$${totalSpent.toFixed(2)}`;


            // Step 3: Update Category Summaries and Total
            categorySummariesEl.innerHTML = ''; // Clear category summaries
            const sortedCategories = Array.from(categoryTotalsMap.keys()).sort();

            sortedCategories.forEach(cat => {
                const total = categoryTotalsMap.get(cat);
                const div = document.createElement('div');
                div.className = 'cat-total';
                div.setAttribute('data-cat', cat);
                div.textContent = `${cat.charAt(0).toUpperCase() + cat.slice(1)}: $${total.toFixed(2)}`;
                categorySummariesEl.appendChild(div);
            });


            // Step 4: Attach Delete Listeners
            document.querySelectorAll('.exp-del').forEach(button => {
                button.addEventListener('click', (e) => {
                    const idToDelete = parseInt(e.target.dataset.id);
                    deleteExpense(idToDelete);
                });
            });

        }


        // --- Event Handlers for Deletion and Filtering ---

        /** Removes an expense by ID from the state and re-renders. */
        function deleteExpense(id) {
            if (confirm("Are you sure you want to delete this expense?")) {
                expenses = expenses.filter(expense => expense.id !== id);
                saveExpenses();
                render(); // Re-render everything after deletion
            }
        }

        /** Handles form submission */
        addButton.addEventListener('click', addExpense);


        // Filter Listeners (Re-run render whenever filter changes)
        const setupFilterListener = (el) => {
            el.addEventListener('change', () => {
                render();
            });
        };

        setupFilterListener(filterCategoryEl);
        setupFilterListener(filterFromEl);
        setupFilterListener(filterToEl);


        // --- Initialization Sequence ---

        function initialize() {
            populateControls(); // Fill down all the dropdowns
            render();          // Render initial state (all expenses)
        }

        initialize();
    });
</script>

</body>
</html>
